custom_css:
/* ============================================================
 * Nord-Dark — SillyTavern 主题
 * Nord 配色（arctic, north-bluish）× 暗版
 * 设计哲学：clean/uncluttered、flat 纯色无渐变、frost 主强调 + aurora 语义强调
 * https://www.nordtheme.com/
 * ============================================================ */

/* ---字体加载--- */
@import url('https://cdn.jsdelivr.net/npm/@fontsource/jetbrains-mono@5.0.0/index.css');

/* ---Nord 原子色（固定，变体不动这层）--- */
:root {
  --nord0:  #2e3440; /* polar0 深底 */
  --nord1:  #3b4252; /* polar1 */
  --nord2:  #434c5e; /* polar2 */
  --nord3:  #4c566a; /* polar3 */
  --nord4:  #d8dee9; /* snow0 正文 */
  --nord5:  #e5e9f0; /* snow1 */
  --nord6:  #eceff4; /* snow2 最亮 */
  --nord7:  #8fbcbb; /* frost0 青绿 */
  --nord8:  #88c0d0; /* frost1 冰青 ★主题色 */
  --nord9:  #81a1c1; /* frost2 雾蓝 */
  --nord10: #5e81ac; /* frost3 深蓝 */
  --nord11: #bf616a; /* aurora0 红/危险 */
  --nord12: #d08770; /* aurora1 橙 */
  --nord13: #ebcb8b; /* aurora2 黄/警告 */
  --nord14: #a3be8c; /* aurora3 绿/成功 */
  --nord15: #b48ead; /* aurora4 紫/信息 */

  /* ---语义令牌（变体只改这层）--- */
  --bg:          var(--nord0);
  --bg-elev:     var(--nord1);   /* 面板/抽屉 */
  --bg-elev2:    var(--nord2);   /* 次级浮层/卡片/按钮底 */
  --bg-sunken:   var(--nord0);  /* 输入框凹陷底 */
  --border:      var(--nord2);
  --border-hi:   var(--nord3);
  --text:        var(--nord4);
  --text-dim:    rgba(216, 222, 233, 0.6);
  --text-faint:  rgba(216, 222, 233, 0.4);
  --accent:      var(--nord8);   /* ★ 主题色，变体唯一替换点 */
  --accent-hi:   var(--nord8);
  --accent-deep: var(--nord10);  /* hover/active 深态 */
  --accent-soft: rgba(136, 192, 208, 0.15);
  --danger:      var(--nord11);
  --warn:        var(--nord13);
  --success:     var(--nord14);
  --info:        var(--nord15);
  --link:        var(--nord8);

  --font-sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', 'Noto Sans', 'PingFang SC', 'Microsoft YaHei', sans-serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', ui-monospace, Menlo, Consolas, monospace;
  --radius: 4px;
}

/* ---全局字体（排除图标，避免盖 FA 字形）--- */
body {
  background-color: transparent !important;
  color: var(--text) !important;
  font-family: var(--font-sans) !important;
}
input, textarea, select, option,
button:not(.fa-solid):not(.fa-regular):not([class*="fa-"]),
.select2-container, .select2-container .select2-selection,
.text_pole, .widthNatural, #send_textarea, #dialogue_del_mes {
  font-family: var(--font-sans) !important;
}
.mes_text, .mes_text p, .mes_text span,
.ch_name, .mesIDDisplay, .mes_timer, .tokenCounterDisplay {
  font-family: var(--font-sans) !important;
  color: var(--text) !important;
}
code, pre, .hljs, .katex {
  font-family: var(--font-mono) !important;
}

/* ---面板/抽屉--- */
.drawer-content,
#left-nav-panel, #right-nav-panel,
#character_popup, #dialogue_popup, .popup,
#top-settings-holder, #send_form,
#WorldInfo, #floatingPrompt, .draggable {
  background-color: var(--bg-elev) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  color: var(--text) !important;
}

/* ---抽屉标题/标题栏--- */
.inline-drawer-header,
.standoutHeader,
.drawer-content h3, .drawer-content h4:not(.margin0),
#character_popup h3, .popup h3, h3 {
  background: var(--bg-elev2) !important;
  color: var(--accent) !important;
  border: none !important;
  border-left: 2px solid var(--accent) !important;
  text-shadow: none !important;
  font-weight: 600 !important;
  padding: 6px 10px !important;
  border-radius: var(--radius) !important;
}
.inline-drawer-header .inline-drawer-icon { color: var(--accent) !important; }

/* ---按钮--- */
.menu_button, .right_menu_button,
input[type="button"], input[type="submit"],
#send_but, #mes_continue {
  background-color: var(--bg-elev2) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  filter: none !important;
  box-shadow: none !important;
  transition: border-color .12s ease, color .12s ease, background-color .12s ease !important;
}
.menu_button:hover, .right_menu_button:hover,
input[type="button"]:hover, input[type="submit"]:hover {
  border-color: var(--accent) !important;
  color: var(--accent) !important;
  background-color: var(--bg-elev2) !important;
}
.menu_button:active, .right_menu_button:active,
input[type="button"]:active, input[type="submit"]:active {
  background-color: var(--accent-deep) !important;
  color: var(--nord6) !important;
  border-color: var(--accent-deep) !important;
}
.menu_button.active, .menu_button.selected {
  background-color: var(--accent-soft) !important;
  color: var(--accent) !important;
  border-color: var(--accent) !important;
}

/* ---输入区--- */
.text_pole, textarea,
input[type="text"], input[type="password"], input[type="number"],
#send_textarea, select {
  background-color: var(--bg-sunken) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.text_pole:focus, textarea:focus,
input[type="text"]:focus, input[type="password"]:focus,
input[type="number"]:focus, #send_textarea:focus, select:focus {
  border-color: var(--accent) !important;
  outline: none !important;
}
.text_pole::placeholder, textarea::placeholder, #send_textarea::placeholder {
  color: var(--text-faint) !important;
  opacity: 1 !important;
}
select option {
  background-color: var(--bg-elev) !important;
  color: var(--text) !important;
}

/* ---聊天区--- */
#chat {
  background-color: var(--bg) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.mes {
  border-bottom: 1px solid var(--border) !important;
}
.mes_text { color: var(--text) !important; }
.mes_block, .mes_text p, .mes_text li { color: var(--text) !important; }
.last_mes .mes_text { color: var(--text) !important; }

/* ---代码块--- */
code, pre {
  background-color: var(--bg-sunken) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.mes_text code, .mes_text pre {
  background-color: var(--bg-sunken) !important;
}
/* hljs 语法高亮：aurora 语义色 */
.hljs { color: var(--text) !important; background: var(--bg-sunken) !important; }
.hljs-keyword, .hljs-selector-tag, .hljs-built_in { color: var(--nord9) !important; }
.hljs-string, .hljs-attr, .hljs-template-string, .hljs-addition { color: var(--nord14) !important; }
.hljs-number, .hljs-literal, .hljs-type, .hljs-constant { color: var(--nord15) !important; }
.hljs-comment, .hljs-quote { color: var(--text-faint) !important; font-style: italic !important; }
.hljs-function .hljs-title, .hljs-title.function_, .hljs-section { color: var(--nord8) !important; }
.hljs-tag, .hljs-name, .hljs-keyword .hljs-name { color: var(--nord11) !important; }
.hljs-attribute, .hljs-variable, .hljs-attr { color: var(--nord8) !important; }
.hljs-meta, .hljs-symbol, .hljs-bullet { color: var(--nord12) !important; }
.hljs-deletion { color: var(--nord11) !important; }
.hljs-emphasis { font-style: italic !important; }
.hljs-strong { font-weight: 700 !important; }

/* ---滚动条--- */
::-webkit-scrollbar { width: 8px !important; height: 8px !important; }
::-webkit-scrollbar-track { background: var(--bg) !important; }
::-webkit-scrollbar-thumb {
  background: var(--border) !important;
  border-radius: var(--radius) !important;
}
::-webkit-scrollbar-thumb:hover { background: var(--accent) !important; }
::-webkit-scrollbar-corner { background: var(--bg) !important; }
* { scrollbar-color: var(--border) var(--bg) !important; scrollbar-width: thin !important; }

/* ---选区与选中态--- */
::selection { background: var(--accent) !important; color: var(--nord0) !important; }
select option:checked, .selected,
.menu_button.selected, .menu_button.active {
  background-color: var(--accent-deep) !important;
  color: var(--nord6) !important;
}

/* ---标签 tag--- */
.tag {
  background-color: var(--bg-elev2) !important;
  color: var(--accent) !important;
  border: 1px solid var(--accent) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
}
.tag::before { color: var(--accent) !important; }

/* ---滑条/勾选/单选--- */
input[type="range"] {
  background: var(--bg-sunken) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  filter: none !important;
  box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-deep) !important;
  border-radius: 50% !important;
  box-shadow: none !important;
}
input[type="range"]::-moz-range-thumb {
  background: var(--accent) !important;
  border: 1px solid var(--accent-deep) !important;
  border-radius: 50% !important;
}
input[type="checkbox"], input[type="radio"] {
  accent-color: var(--accent) !important;
}

/* ---弹窗/toastr--- */
.toast, .toast-container .toast {
  background-color: var(--bg-elev2) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-left: 3px solid var(--accent) !important;
  border-radius: var(--radius) !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
.toast-success, .toast-container .toast-success { border-left-color: var(--success) !important; }
.toast-error, .toast-container .toast-error { border-left-color: var(--danger) !important; }
.toast-warning, .toast-container .toast-warning { border-left-color: var(--warn) !important; }
.toast-info, .toast-container .toast-info { border-left-color: var(--info) !important; }

/* ---头像--- */
.avatar, .avatar img {
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
}

/* ---顶栏图标--- */
#top-settings-holder .drawer-icon {
  color: var(--text) !important;
  text-shadow: none !important;
}
#top-settings-holder .drawer-icon:hover { color: var(--accent) !important; }

/* ---链接--- */
a, a:visited { color: var(--link) !important; text-decoration: none !important; }
a:hover { color: var(--accent-hi) !important; text-decoration: underline !important; }

/* ---工具提示 tooltip--- */
.tooltip, [data-toggle="tooltip"] + .tooltip, .tooltip-inner, .tooltip-arrow {
  background-color: var(--bg-elev2) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  text-shadow: none !important;
  box-shadow: none !important;
}

/* ---角色列表条目/世界书条目分割线--- */
.character_div, .character_select,
#WorldInfo .world_entry,
.prompt_manager_prompt_entry,
.world_info_entry {
  border-bottom: 1px solid var(--border) !important;
  background-color: var(--bg-elev) !important;
}
.character_div:hover, .character_select:hover {
  background-color: var(--bg-elev2) !important;
}

/* ---分割线统一--- */
hr, .drawer-content hr,
.mes hr, .mes_text hr {
  border: none !important;
  border-top: 1px solid var(--border) !important;
}

/* ---发送按钮 hover 微光（Nord 极克制，仅此一处）--- */
#send_but:hover, #mes_continue:hover {
  box-shadow: 0 0 8px rgba(136, 192, 208, 0.4) !important;
  border-color: var(--accent) !important;
  color: var(--accent) !important;
}

/* ---现代病克制：去文字阴影/动画抖动--- */
* { text-shadow: none !important; }
.mes, .drawer-content { animation: none !important; }

/* ============================================================
 * modern-ui 插件适配（body.th-modern-enabled 限定，纯 ST 零命中）
 * 顶层规则，不塞桌面媒体查询，手机生效
 * ============================================================ */
body.th-modern-enabled .th-modern-wi-entry,
body.th-modern-enabled .th-modern-wi-list,
body.th-modern-enabled [class^="th-modern-wi"] {
  background-color: var(--bg-elev) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
  color: var(--text) !important;
}
body.th-modern-enabled .th-modern-panel-header,
body.th-modern-enabled .th-modern-section-title,
body.th-modern-enabled .th-modern-wi-header {
  background: var(--bg-elev2) !important;
  color: var(--accent) !important;
  border-left: 2px solid var(--accent) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-wi-shortcut-control,
body.th-modern-enabled input.th-modern-wi-shortcut-control,
body.th-modern-enabled select.th-modern-wi-shortcut-control {
  background-color: var(--bg-sunken) !important;
  color: var(--text) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card,
body.th-modern-enabled .th-modern-item {
  background-color: var(--bg-elev) !important;
  border: 1px solid var(--border) !important;
  border-radius: var(--radius) !important;
}
body.th-modern-enabled .th-modern-card:hover,
body.th-modern-enabled .th-modern-item:hover {
  border-color: var(--accent) !important;
}

/* ---modern-ui select 弹层主题化（PC 专用，塞桌面媒体）--- */
@media (hover: hover) and (pointer: fine) {
  body.th-modern-enabled .select2-container--default .select2-results__option--highlighted[aria-selected] {
    background-color: var(--accent-deep) !important;
    color: var(--nord6) !important;
  }
  body.th-modern-enabled .select2-container--default .select2-selection--single {
    background-color: var(--bg-sunken) !important;
    color: var(--text) !important;
    border: 1px solid var(--border) !important;
    border-radius: var(--radius) !important;
  }
}
